export function registerServiceWorker(){"serviceWorker"in navigator&&window.addEventListener("load",()=>{navigator.serviceWorker.register("/sw.js").catch(r=>{console.error("Service Worker \u043D\u0435 \u0437\u0430\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043E\u0432\u0430\u043D",r)})})}export function notifyServiceWorker(r){var e,o;(o=(e=navigator.serviceWorker)==null?void 0:e.controller)==null||o.postMessage(r)}
